'use client';

import { useQuery } from '@tanstack/react-query';
import { Coins, TrendingUp } from 'lucide-react';
import StatCard from './StatCard';

export default function KSCTokenCard() {
  const { data: balances, isLoading } = useQuery({
    queryKey: ['ksc-balances'],
    queryFn: async () => {
      const res = await fetch('http://localhost:4000/api/tokens/balances');
      return res.json();
    },
    refetchInterval: 10000, // Refresh every 10 seconds
  });

  const { data: stats } = useQuery({
    queryKey: ['ksc-stats'],
    queryFn: async () => {
      const res = await fetch('http://localhost:4000/api/tokens/stats');
      return res.json();
    },
    refetchInterval: 10000,
  });

  if (isLoading) {
    return (
      <div className="col-span-2 bg-white rounded-lg border border-gray-200 p-6 animate-pulse">
        <div className="h-8 bg-gray-200 rounded w-1/3 mb-4"></div>
        <div className="h-24 bg-gray-200 rounded"></div>
      </div>
    );
  }

  return (
    <div className="col-span-2 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-lg border border-blue-200 p-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
            <Coins className="w-5 h-5 text-blue-600" />
            KSC Token (KazSmartChain Token)
          </h3>
          <p className="text-sm text-gray-600 mt-1">Native utility token</p>
        </div>
        <div className="text-right">
          <div className="text-2xl font-bold text-blue-600">
            {balances?.totalSupply || '0'} KSC
          </div>
          <div className="text-xs text-gray-500">Total Supply</div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4 mb-6">
        <div className="bg-white rounded-lg p-4">
          <div className="text-xs text-gray-500 mb-1">Total Minted</div>
          <div className="text-xl font-semibold text-green-600">
            {stats?.totalMinted || '0'}
          </div>
          <div className="text-xs text-gray-400 mt-1">
            {stats?.mintCount || 0} mints
          </div>
        </div>

        <div className="bg-white rounded-lg p-4">
          <div className="text-xs text-gray-500 mb-1">Total Transferred</div>
          <div className="text-xl font-semibold text-blue-600">
            {stats?.totalTransferred || '0'}
          </div>
          <div className="text-xs text-gray-400 mt-1">
            {stats?.transferCount || 0} transfers
          </div>
        </div>

        <div className="bg-white rounded-lg p-4">
          <div className="text-xs text-gray-500 mb-1">Total Burned</div>
          <div className="text-xl font-semibold text-red-600">
            {stats?.totalBurned || '0'}
          </div>
          <div className="text-xs text-gray-400 mt-1">
            {stats?.burnCount || 0} burns
          </div>
        </div>
      </div>

      <div className="space-y-3">
        <h4 className="text-sm font-semibold text-gray-700">
          Organization Balances / Балансы организаций
        </h4>
        {balances?.balances?.map((org: any, idx: number) => (
          <div
            key={idx}
            className="bg-white rounded-lg p-4 flex items-center justify-between hover:shadow-md transition-shadow"
          >
            <div className="flex-1">
              <div className="font-medium text-gray-900">{org.organization}</div>
              <div className="text-xs text-gray-500 font-mono">{org.address}</div>
            </div>
            <div className="text-right">
              <div className="text-lg font-bold text-blue-600">
                {org.balance} KSC
              </div>
              <div className="text-xs text-gray-500">
                {((org.balanceRaw / balances.totalSupplyRaw) * 100).toFixed(2)}% of supply
              </div>
            </div>
          </div>
        ))}
      </div>

      <div className="mt-6 flex items-center justify-between text-xs text-gray-500">
        <div>Contract: {balances?.token?.address?.slice(0, 10)}...{balances?.token?.address?.slice(-8)}</div>
        <div className="flex items-center gap-1">
          <TrendingUp className="w-3 h-3" />
          Live updates every 10s
        </div>
      </div>
    </div>
  );
}

